class Solution {
  public long[] resultArray(int[] nums, int k) {
    long[] result = new long[k];
    long[] ending = new long[k]; // subarrays ending at the current index, by product remainder
    for (int a : nums) {
      long[] next = new long[k];
      int r = a % k;
      for (int x = 0; x < k; x++) next[x * r % k] += ending[x];
      next[r]++;
      for (int x = 0; x < k; x++) result[x] += next[x];
      ending = next;
    }
    return result;
  }
}
